<script setup>
import {computed,inject,nextTick,onMounted,reactive,ref} from 'vue'
import {api} from '../api.js'
import LearningWalkthrough from '../components/LearningWalkthrough.vue'
import LearningWritingExample from '../components/LearningWritingExample.vue'
const work=inject('workspace'),rag=inject('retrieval')
const exampleMethod=ref('RERANK_TOGGLE')
function openExperiment(){work.go(rag.state.baseline?'evaluate':'knowledge')}
const pack=ref(null),attempt=ref(null),history=ref([]),summary=ref(null)
const busy=ref(false),loading=ref(true),error=ref(''),mode=ref('TRAINING'),caseId=ref('p01')
const form=reactive({judgment:'',evidence_id:'',quote:'',candidate_causes:[],uncertainty:'',distinguishing_check:'',source:'SELF'})
const prediction=reactive({choice:'APPLY',expected_result:'',potential_cost:'',reason:''}),decision=reactive({decision:'DECLINE',reason:'',limitations:''})
const formStep=ref(1),editing=ref(false),formHeading=ref(null),stageHeading=ref(null),showWalkthrough=ref(false)
const exitReason=ref('TIME'),exitNote=ref(''),feedbackValue=ref('PARTLY'),feedbackNote=ref('')
const stageLabels={STARTED:'刚开始',JUDGED:'已写下看法',PREDICTED:'已保存预测',REPLAYED:'已看过结果',DECIDED:'已作出决定',TRANSFER:'正在做新题',COMPLETE_PENDING_REVIEW:'已完成，尚待点评',EXITED:'已结束',TECHNICAL_FAILED:'遇到技术问题'}
const eventLabels={practice_started:'开始练习',initial_judgment_saved:'写下最初的看法',hint_revealed:'查看提示',diagnosis_revised:'修改看法',prediction_saved:'预测改动结果',verification_completed:'查看示例结果',adoption_decided:'作出决定',transfer_started:'开始新题',transfer_submitted:'提交新题',transfer_feedback_revealed:'查看新题解析',feedback_recorded:'留下反馈',practice_exited:'结束练习',practice_failed:'记录技术问题'}
const sourceLabels={SELF:'自己想的',AI_ASSISTED:'参考了 AI',EXTERNAL_HELP:'参考了其他帮助',AI_TEACHING_HINT:'看过练习提示'}
const causeLabels={DATA:'资料或记录有问题',PROMPT:'评分模型看错了',RUBRIC:'评分规则不合理',AGENT:'客服回答有问题',UNCERTAIN:'还说不准'}
const terminal=computed(()=>['EXITED','TECHNICAL_FAILED','COMPLETE_PENDING_REVIEW'].includes(attempt.value?.stage))
const transfer=computed(()=>attempt.value?.stage==='TRANSFER'),trace=computed(()=>attempt.value?.transfer||attempt.value?.case)
const showForm=computed(()=>attempt.value&&!terminal.value&&(['STARTED','TRANSFER'].includes(attempt.value.stage)||(editing.value&&attempt.value.stage==='JUDGED')))
const currentStep=computed(()=>!attempt.value?0:attempt.value.stage==='STARTED'?0:['JUDGED','PREDICTED'].includes(attempt.value.stage)?1:['REPLAYED','DECIDED'].includes(attempt.value.stage)?2:3)
const sources=computed(()=>[...(trace.value?.evidence||[]),{evidence_id:'answer',text:trace.value?.answer||''}])
const firstStepReady=computed(()=>form.judgment.trim().length>=2&&form.evidence_id&&form.quote.trim().length>=2)
const latestJudgment=computed(()=>[...(attempt.value?.events||[])].reverse().find(e=>['diagnosis_revised','initial_judgment_saved'].includes(e.name))?.payload.judgment)
const predictionKept=computed(()=>attempt.value?.events.some(e=>e.name==='prediction_saved'&&e.payload.choice==='KEEP'))
const actionIds=new Map()
async function startPractice(id){if(attempt.value){showWalkthrough.value=false;await nextTick();document.querySelector('.learning-evidence')?.scrollIntoView({block:'start',behavior:'smooth'});return}if(id)caseId.value=id;if(await act('start',{case_id:caseId.value,mode:mode.value}))showWalkthrough.value=false}
function resetForm(saved){Object.assign(form,{judgment:'',evidence_id:'',quote:'',candidate_causes:[],uncertainty:'',distinguishing_check:'',source:'SELF'});if(saved)Object.assign(form,{judgment:saved.judgment,evidence_id:saved.evidence?.[0]?.evidence_id||'',quote:saved.evidence?.[0]?.quote||'',candidate_causes:[...saved.candidate_causes],uncertainty:saved.uncertainty,distinguishing_check:saved.distinguishing_check,source:saved.source});formStep.value=1;editing.value=false}
function another(){attempt.value=null;localStorage.removeItem('agenteval.learning.attempt');resetForm();window.scrollTo({top:0,behavior:'smooth'})}
async function reload(){history.value=await api.get('/learning/attempts');summary.value=await api.get('/learning/summary')}
async function focusForm(){await nextTick();formHeading.value?.scrollIntoView({behavior:'smooth',block:'start'});formHeading.value?.focus({preventScroll:true})}
function pickEvidence(id){form.evidence_id=id;form.quote=sources.value.find(e=>e.evidence_id===id)?.text||''}
async function useEvidence(e){pickEvidence(e.evidence_id);formStep.value=1;await focusForm()}
async function nextFormStep(){if(!firstStepReady.value)return;formStep.value=2;await focusForm()}
async function revise(){resetForm(latestJudgment.value);editing.value=true;await focusForm()}
async function act(name,payload={}){
 if(busy.value)return false
 busy.value=true;error.value=''
 try{
  const fingerprint=JSON.stringify({name,payload,id:attempt.value?.attempt_id}),request_id=actionIds.get(fingerprint)||crypto.randomUUID();actionIds.set(fingerprint,request_id)
  attempt.value=await api.post(name==='start'?'/learning/attempts':`/learning/attempts/${attempt.value.attempt_id}/${name}`,{...payload,request_id})
  actionIds.delete(fingerprint);localStorage.setItem('agenteval.learning.attempt',attempt.value.attempt_id)
  if(name==='start'||name==='transfer-start'){resetForm();Object.assign(prediction,{choice:'APPLY',expected_result:'',potential_cost:'',reason:''});Object.assign(decision,{decision:'DECLINE',reason:'',limitations:''})}
  if(name==='initial'||name==='revision')editing.value=false
  if(name==='replay'&&attempt.value.events.find(e=>e.name==='prediction_saved')?.payload.choice==='KEEP')decision.decision='KEEP'
  await reload();await nextTick();if(name==='start'||name==='transfer-start')document.querySelector('.learning-evidence')?.scrollIntoView({block:'start',behavior:'smooth'});else if(['initial','replay','decision'].includes(name)){stageHeading.value?.focus({preventScroll:true});stageHeading.value?.scrollIntoView({block:'start',behavior:'smooth'})}return true
 }catch(e){error.value=e.message||'这一步没有完成，请再试一次。'}finally{busy.value=false}
 return false
}
async function open(id){busy.value=true;error.value='';try{attempt.value=await api.get('/learning/attempts/'+id);resetForm(latestJudgment.value);const plan=attempt.value.events.find(e=>e.name==='prediction_saved')?.payload;const saved=attempt.value.events.find(e=>e.name==='adoption_decided')?.payload;Object.assign(prediction,{choice:'APPLY',expected_result:'',potential_cost:'',reason:''},plan||{});Object.assign(decision,{decision:plan?.choice==='KEEP'?'KEEP':'DECLINE',reason:'',limitations:''},saved||{});localStorage.setItem('agenteval.learning.attempt',id)}catch(e){error.value=e.message}finally{busy.value=false}}
async function submit(){if(formStep.value!==2)return nextFormStep();if(!firstStepReady.value)return;await act(transfer.value?'transfer-submit':editing.value?'revision':'initial',{judgment:form.judgment,evidence:[{evidence_id:form.evidence_id,quote:form.quote}],candidate_causes:form.candidate_causes,uncertainty:form.uncertainty,distinguishing_check:form.distinguishing_check,source:form.source})}
async function predict(){if(await act('prediction',{...prediction}))await act('replay')}
async function download(){try{const data=await api.get(`/learning/attempts/${attempt.value.attempt_id}/export`),url=URL.createObjectURL(new Blob([data.markdown],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=data.filename;a.click();URL.revokeObjectURL(url)}catch(e){error.value=e.message}}
onMounted(async()=>{try{pack.value=await api.get('/learning/pack');await reload();const id=localStorage.getItem('agenteval.learning.attempt');if(history.value.some(a=>a.attempt_id===id))await open(id)}catch(e){error.value=e.message}finally{loading.value=false}})
</script>

<template>
 <div class="learning-page">
  <header class="page-heading"><div><p class="eyebrow">新手入门 · 不需要 API Key</p><h1>{{attempt?'跟着做一道题':'先看五种改法怎么选'}}</h1><p>{{attempt?'跟着步骤看资料、找问题，再决定怎么改。':'先找出问题所在，再选择修改，最后用原题复测。'}}</p></div><div class="button-row"><button v-if="attempt" class="text-button" @click="showWalkthrough=!showWalkthrough">{{showWalkthrough?'收起完整示范':'回看完整示范'}}</button><button class="text-button" @click="work.go('setup')">用自己的模型做实验 →</button></div></header>
  <p v-if="error" class="note danger" role="alert">{{error}}</p><p v-if="loading" class="note" role="status">正在读取练习…</p>
  <LearningWalkthrough v-if="(!attempt&&!loading)||showWalkthrough" v-model:method-id="exampleMethod" @experiment="openExperiment" :busy="busy||!pack" :resume="!!attempt" @practice="startPractice('p01')" />
  <details v-if="!attempt&&!loading" class="panel practice-start"><summary>练习：核对证据与评分</summary>
   <h2>{{caseId==='p01'?'从一笔退款说起':pack?.cases.find(c=>c.case_id===caseId)?.title}}</h2><p>{{caseId==='p01'?'客服说“已经退了 80 元”，记录里也有 80 元。这就能证明它答对了吗？':'先看看客服回答和手边的资料，再说说你的看法。'}}</p>
   <div class="start-action"><button class="primary" :disabled="busy||!pack" @click="startPractice()">开始练习 →</button><span class="muted">模拟题，不会调用模型或产生费用。</span></div>
   <details class="practice-options"><summary>换一道题，或直接看解析</summary><label>选择题目<select v-model="caseId"><option v-for="c in pack?.cases||[]" :key="c.case_id" :value="c.case_id">{{c.title}}</option></select></label><label>怎么练<select v-model="mode"><option value="TRAINING">先自己想，再按需看提示</option><option value="FREE">边看解析边练</option></select></label><p class="muted">直接看解析的题会记为复习。</p></details>
  </details>
  <template v-if="attempt">
   <ol class="practice-progress" aria-label="练习进度"><li v-for="(label,index) in ['看回答','想改法','看结果','再试一题']" :key="label" :class="{current:currentStep===index,done:currentStep>index}" :aria-current="currentStep===index?'step':undefined"><span>{{currentStep>index?'✓':index+1}}</span>{{label}}</li></ol>
   <details class="panel learning-evidence" :open="!terminal"><summary>{{attempt.transfer?'新题：':'这道题：'}}{{trace?.title}}</summary>
    <div class="question-answer"><div><p class="eyebrow">用户问</p><p>{{trace?.question}}</p></div><div><p class="eyebrow">客服回答</p><p>{{trace?.answer}}</p></div></div>
    <h3>你手边的资料</h3><article v-for="(e,index) in trace?.evidence||[]" :key="e.evidence_id" class="evidence-card"><div class="evidence-heading"><strong>资料 {{index+1}}</strong><small>{{e.scope==='HISTORY'?'之前的对话':'本轮资料'}} · {{e.object_id}} · 第 {{e.turn}} 轮</small></div><blockquote>{{e.text}}</blockquote><button v-if="showForm" type="button" class="text-button" :disabled="busy" @click="useEvidence(e)">引用这条</button></article>
    <p v-if="trace?.machine_verdict" class="muted">评分模型原来判为“{{trace.machine_verdict==='PASS'?'通过':'不通过'}}”，你可以有不同看法。</p><p v-if="transfer" class="note">{{attempt.transfer_independent_eligible?'这次先自己想，提交后再看参考思路。':'这道题你已做过，或当前正在看解析练习；这次记为复习。'}}</p>
   </details>
   <section v-if="attempt.mode==='FREE'&&attempt.stage==='STARTED'&&attempt.reference" class="panel reference-note"><h2>边看解析边练</h2><p>{{attempt.reference.analysis}}</p><p class="muted">参考解析待人工复核，这次会记为复习。</p></section>
   <section v-if="showForm" class="panel judgment-panel"><p class="eyebrow">{{transfer?'新题':editing?'修改看法':'跟着试一题'}} · {{formStep}} / 2</p><h2 ref="formHeading" tabindex="-1">{{formStep===1?'这句回答能信吗？':'你觉得问题可能出在哪？'}}</h2>
    <form @submit.prevent="submit"><div v-if="formStep===1"><p class="muted">先读上面的用户问题和 Agent 回答，再对照资料。写一句你能确认的事，然后引用支持它的原文。</p><LearningWritingExample v-model:method-id="exampleMethod" v-if="!transfer" stage="judgment" /><label>你的看法<textarea v-model="form.judgment" rows="3" required minlength="2" placeholder="这句回答哪里有依据、哪里还不能确认？写明理由。" /></label><label>哪条资料让你这样想？<select v-model="form.evidence_id" required @change="pickEvidence(form.evidence_id)"><option value="">选择一条，或点击上面的“引用这条”</option><option v-for="(e,index) in sources" :key="e.evidence_id" :value="e.evidence_id">{{e.evidence_id==='answer'?'客服回答':'资料 '+(index+1)}} · {{e.text}}</option></select></label><label>引用的原文<textarea v-model="form.quote" rows="2" required minlength="2" placeholder="选中资料后会带入原文，你可以只保留相关的一句" /></label><button type="button" class="primary" :disabled="busy||!firstStepReady" @click="nextFormStep">接着想想原因 →</button><p class="muted draft-note">下一步可以回头修改，提交后才会保存。</p></div>
    <div v-else><p class="muted">先记录猜测，再写出能验证它的下一步。拿不准时可以选“还说不准”。</p><LearningWritingExample v-model:method-id="exampleMethod" v-if="!transfer" stage="cause" /><fieldset><legend>先选你的猜测，可以多选</legend><label v-for="(label,key) in causeLabels" :key="key" class="check"><input v-model="form.candidate_causes" type="checkbox" :value="key" />{{label}}</label></fieldset><label>还有什么没弄清？<textarea v-model="form.uncertainty" rows="2" required minlength="2" placeholder="哪些信息还不够？如果已经清楚，也说说为什么。" /></label><label>你会再查什么？<textarea v-model="form.distinguishing_check" rows="2" required minlength="2" placeholder="怎样知道自己的猜测对不对？" /></label><label>这次怎么想出来的？<select v-model="form.source"><option value="SELF">自己想的</option><option value="AI_ASSISTED">参考了其他 AI</option><option value="EXTERNAL_HELP">参考了他人或其他资料</option></select></label><div class="button-row"><button class="primary" :disabled="busy||!form.candidate_causes.length">{{transfer?'提交这道题':editing?'更新我的看法':'保存我的看法'}}</button><button type="button" class="text-button" :disabled="busy" @click="formStep=1">← 回去看看</button></div></div></form>
   </section>
   <template v-if="attempt.stage==='JUDGED'&&!editing">
    <section class="panel saved-thought"><h2>你刚才的看法</h2><p>{{latestJudgment?.judgment}}</p><button class="text-button" :disabled="busy" @click="revise">改一下刚才的想法</button></section>
    <section class="panel practice-hints"><div class="section-heading"><h2>卡住了？看看提示</h2><small v-if="attempt.highest_hint">已看 {{attempt.highest_hint}} 条提示</small></div><p v-for="(hint,i) in attempt.hints" :key="i" class="hint-text">{{hint}}</p><button v-if="attempt.highest_hint<3" class="secondary" :disabled="busy" @click="act('hint',{level:attempt.highest_hint+1})">{{['给我一点提示','再给一个提示','看看参考思路'][attempt.highest_hint]}}</button><div v-if="attempt.reference" class="reference-note"><h3>参考思路 <small>待人工复核</small></h3><p>{{attempt.reference.analysis}}</p><details><summary>还可以考虑什么？</summary><p>{{attempt.reference.alternatives}}</p><p>{{attempt.reference.verification}}</p></details></div></section>
    <section class="panel prediction-panel"><h2 ref="stageHeading" tabindex="-1">试试这个改法</h2><p class="muted">先读候选改法，再预测它能解决什么、可能影响什么。下面有另一道题的填写示范。</p><LearningWritingExample v-model:method-id="exampleMethod" stage="prediction" /><p class="proposed-change">{{attempt.proposed_change}}</p><form @submit.prevent="predict"><label>你想怎么试？<select v-model="prediction.choice"><option value="APPLY">看看这个改法的结果</option><option value="KEEP">先不试改，继续核查</option></select></label><label>你猜结果会怎样？<textarea v-model="prediction.expected_result" rows="2" required minlength="2" placeholder="写明你希望哪句回答发生什么变化；暂不修改时，写接下来想核查什么。" /></label><label>可能带来什么新问题？<textarea v-model="prediction.potential_cost" rows="2" required minlength="2" placeholder="比如：会不会把本来答对的情况也拒绝，或问了不必要的问题？" /></label><label>为什么这样选？<textarea v-model="prediction.reason" rows="2" required minlength="2" placeholder="结合当前题目的资料，说明为什么值得这样试，或为什么暂时不试。" /></label><button class="primary" :disabled="busy">保存预测，看看结果 →</button><p class="muted draft-note">这里展示预设的练习结果，不会实时调用模型。</p></form></section>
   </template>
   <section v-if="attempt.stage==='PREDICTED'" class="panel"><h2>预测已保存</h2><p>接下来看看预设的练习结果，和你想的一样吗？</p><button class="primary" :disabled="busy" @click="act('replay')">查看示例结果 →</button></section>
   <section v-if="attempt.replay&&!attempt.transfer" class="panel decision-panel">
    <h2 ref="stageHeading" tabindex="-1">对照结果，决定下一步</h2>
    <div class="decision-context"><p><strong>刚才的问题：</strong>{{attempt.case.question}}</p><p><strong>候选改法：</strong>{{attempt.proposed_change}}</p></div>
    <p v-if="predictionKept" class="note">你刚才选择先不试改，所以这次还没有改后的回答。现在可以记录为什么暂时不改，以及下一步需要核查什么；这不代表原回答已经正确。</p>
    <template v-else><p class="muted">先看原来的问题有没有改善，再看有没有影响其他情况。这些是预设的练习结果。</p><dl class="replay-results"><div v-for="(value,key) in attempt.replay" :key="key"><dt>{{({target:'原来的问题',regression:'其他影响',decision_guidance:'怎么取舍'})[key]||key}}</dt><dd>{{value}}</dd></div></dl></template>
    <form v-if="attempt.stage==='REPLAYED'" @submit.prevent="act('decision',{...decision})">
     <LearningWritingExample v-model:method-id="exampleMethod" stage="decision" :kept="predictionKept" />
     <label>你的决定<select v-model="decision.decision"><template v-if="predictionKept"><option value="KEEP">暂不试改，继续核查</option></template><template v-else><option value="DECLINE">不用这个改法</option><option value="KEEP">保留原来的做法</option><option value="ADOPT">在这次试过的范围内使用</option><option value="CONTINUE_OBSERVING">还需要再试试</option></template></select></label>
     <label>为什么？<textarea v-model="decision.reason" rows="3" required minlength="2" :placeholder="predictionKept?'说明为什么暂时不改，以及还缺少什么判断依据。':'结合上面的结果，说明哪些改善、哪些没改善，为什么这样决定。'" /></label>
     <label>还有哪些情况没试过？<textarea v-model="decision.limitations" rows="3" required minlength="2" placeholder="写出还没验证的问法、条件或数据，以及准备怎样补查。" /></label>
     <p class="muted draft-note">这两项不需要写成报告。各写一两句、说清依据和下一步就可以。</p><button class="primary" :disabled="busy">记下我的决定</button>
    </form><div v-if="attempt.stage==='DECIDED'"><p>这次已经按步骤做完。接下来换一道类似的新题，先自己判断，再看解析。</p><button class="primary" :disabled="busy" @click="act('transfer-start')">再试一道类似的题 →</button></div>
   </section>
   <section v-if="attempt.stage==='COMPLETE_PENDING_REVIEW'" class="panel practice-complete"><p class="eyebrow">这次练习已完成</p><h2>看看你和参考思路有什么不同</h2><p>{{attempt.transfer_reference?.analysis}}</p><details><summary>可以怎样检查自己的想法？</summary><p>{{attempt.transfer_reference?.verification}}</p></details><p class="muted">{{attempt.review_status==='MEETS_CRITERIA'?'这份新题回答已由人工点评，符合本次练习要求。':attempt.review_status==='NOT_YET'?'人工点评认为还需要练习，可以回看题目和自己的记录。':'新题回答已保存，尚未人工点评。参考解析也在复核中。'}}一次练习不能说明已经掌握。</p><div class="button-row"><button class="primary" @click="download">下载练习记录</button><button class="secondary" :disabled="busy" @click="another">选另一道题</button></div><details class="practice-feedback"><summary>这道练习有帮助吗？</summary><label>帮助程度<select v-model="feedbackValue"><option value="YES">有帮助</option><option value="PARTLY">部分有帮助</option><option value="NO">没有帮助</option></select></label><label>想说点什么？<textarea v-model="feedbackNote" rows="2" /></label><button class="secondary" :disabled="busy" @click="act('feedback',{helpful:feedbackValue,note:feedbackNote})">留下反馈</button></details></section>
   <p v-if="['EXITED','TECHNICAL_FAILED'].includes(attempt.stage)" class="note">这次练习已结束，之前写下的内容都还在。<button class="text-button" @click="another">重新选题 →</button></p>
   <details class="panel practice-record"><summary>回看我的思考过程</summary><p>最初的看法：{{attempt.initial_independent?'自己完成':'看过解析或使用了帮助，或尚未提交'}} · 已看 {{attempt.highest_hint}} 条提示</p><ol><li v-for="e in attempt.events" :key="e.event_id"><strong>{{eventLabels[e.name]||'保存记录'}}</strong><small>{{new Date(e.created_at).toLocaleString('zh-CN')}}</small><p v-if="e.payload.judgment">{{e.payload.judgment.judgment}} · {{sourceLabels[e.payload.assistance]||'已记录协助来源'}}</p></li></ol><button class="secondary" @click="download">下载已有记录</button></details>
   <details v-if="!terminal" class="practice-pause"><summary>先到这里</summary><p class="muted">结束后不能接着填写这次练习，但可以回看记录或重新选题。</p><label>这次为什么停下？<select v-model="exitReason"><option value="TIME">时间不够了</option><option value="DIFFICULT">有点难</option><option value="NOT_RELEVANT">暂时用不上</option><option value="TECHNICAL">页面或操作出了问题</option><option value="OTHER">其他</option></select></label><label>补充说明（可选）<textarea v-model="exitNote" rows="2" /></label><button class="secondary" :disabled="busy" @click="act(exitReason==='TECHNICAL'?'technical-failure':'exit',{reason:exitReason,note:exitNote})">保存记录，结束这次练习</button></details>
  </template>
  <details v-if="history.length" class="panel practice-history"><summary>我的练习记录 · {{history.length}}</summary><button v-for="a in history" :key="a.attempt_id" class="history-row" :disabled="busy" @click="open(a.attempt_id)"><span><strong>{{a.title}}</strong><small>{{stageLabels[a.stage]||'已有记录'}}</small></span><span>→</span></button><details v-if="summary"><summary>查看进度统计</summary><p>开始 {{summary.attempts_started}} 次 · 写下看法 {{summary.first_judgment_completed}} 次 · 中途结束 {{summary.exited}} 次 · 技术问题 {{summary.technical_failures}} 次</p><p>开始新题 {{summary.transfer_entered}} 次 · 未看解析提交 {{summary.transfer_independent_submitted}} 次 · 未提交 {{summary.transfer_unsubmitted}} 次 · 待人工点评 {{summary.pending_human_review}} 次 · 人工确认符合要求 {{summary.verified_meets_criteria}} 次</p><p class="muted">按练习次数统计，不代表人数。新题表现以全部开始新题的次数为分母，保留未提交和待点评的记录。</p></details></details>
  <details v-if="pack" class="practice-about"><summary>关于这些练习</summary><p>共有 8 道模拟练习和 4 道类似的新题。题目和结果是预先编写的，不是真实订单记录，也不会发起模型请求。参考解析仍需人工复核。</p><p>系统会保存你的看法、用过的提示和修改过程。看过答案的题记为复习；你的作答不会自动变成评分标准。</p></details>
 </div>
</template>

